usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Beta.Threads.Update(
		context.TODO(),
		"thread_id",
		openai.BetaThreadUpdateParams{
			ToolResources: openai.ModifyThreadRequestToolResources{CodeInterpreter: openai.ModifyThreadRequestToolResourcesCodeInterpreter{FileIds: []string{"string"}}, FileSearch: openai.ModifyThreadRequestToolResourcesFileSearch{VectorStoreIds: []string{"string"}}},
			Metadata: map[string]string{"key": "string"},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
